config:

    {{ product }}
    {{ username }}
    {{ password }}
    {{ rest_url }}


    {{ luntype }}
    {{ lun_clone_mode }}
    {{ lun_copy_speed }}
    {{ storage_pool }}

{% if protocol == "iscsi" %}

    {% if default_targetip != '' -%}
    {{ default_targetip }}
    {% endif %}
    {% if initiator_name != '' -%}
    {% set initiators = initiator_name.split(';') %}
    {% for initiator in initiators -%}

    {% endfor %}
    {% endif %}

{% endif %}
{% if protocol == "fc" %}

    {% if fc_minonlinefcinitiator > -1 -%}
    {{ fc_minonlinefcinitiator }}
    {% endif %}
    {% if fc_hostname != '' -%}
    {% set hostnames = fc_hostname.split(';') %}
    {% for hostname in hostnames -%}

    {% endfor %}
    {% endif %}

{% endif %}
